-- !!! DEV-ONLY SEED DUMP - DO NOT PUT UNDER sql/updates/ !!!
-- This file WIPES the auth database (DELETE FROM account, battlenet_accounts, ...)
-- and inserts throwaway developer test rows. It must only ever be applied by hand
-- to a disposable dev database. See sql/custom/dev-seed/README.md.
-- Applying it to a live realm deletes every existing account (logins fail with
-- "unknown account" while new accounts work) and cannot be undone - restore from backup.

--
-- Test/dev seed data for the auth database (accounts, battle.net links, realm character
-- counts, etc). This is throwaway test data for this project's dev environment, not real
-- player data.
--
-- Each table is fully replaced (DELETE then re-INSERT) rather than appended, so this file is
-- safe to re-run and safe on a fresh install that might already have empty versions of these
-- tables. FOREIGN_KEY_CHECKS is disabled for the duration so table order doesn't matter.
--
-- NOT included here (handled separately or intentionally excluded):
--   build_info / realmlist default   -> sql/updates/auth/3.4.3/2026_08_10_00_auth.sql
--   rbac_permissions / rbac_default_permissions / rbac_linked_permissions -> unmodified
--       stock TrinityCore data, not project-specific, not shipped here
--   realmlist                        -> per-operator config, not shipped as data
--   updates_include                  -> updater bootstrap config, not shipped as data
--   uptime                           -> operational log history, not seed data, excluded
--

SET FOREIGN_KEY_CHECKS = 0;

-- account
DELETE FROM `account`;

-- account_access
DELETE FROM `account_access`;

-- account_last_played_character
DELETE FROM `account_last_played_character`;

-- battle_pet_slots
DELETE FROM `battle_pet_slots`;

-- battle_pets
DELETE FROM `battle_pets`;

-- battlenet_account_heirlooms
DELETE FROM `battlenet_account_heirlooms`;

-- battlenet_account_mounts
DELETE FROM `battlenet_account_mounts`;

-- battlenet_account_toys
DELETE FROM `battlenet_account_toys`;

-- battlenet_accounts
DELETE FROM `battlenet_accounts`;

-- battlenet_item_appearances
DELETE FROM `battlenet_item_appearances`;

-- battlepay_purchases
DELETE FROM `battlepay_purchases`;

-- realmcharacters
DELETE FROM `realmcharacters`;

SET FOREIGN_KEY_CHECKS = 1;
